using System;using UnityEngine;
public class CreeperSimulation {
 public Mesh[] sectionMeshes,powerSectionMeshes;public MeshFilter[] filters,powerFilters;public int[] payload;
 public void Start(){sectionMeshes=new Mesh[filters.Length];powerSectionMeshes=new Mesh[filters.Length];payload=new int[filters.Length];for(int i=0;i<filters.Length;i++){sectionMeshes[i]=filters[i].mesh;payload[i]=i+7;Mesh.events.Add("store:"+i);powerSectionMeshes[i]=powerFilters[i].mesh;}}
 static void Main(string[]args){bool patched=args[0]=="patched";int checks=0;foreach(int n in new[]{0,1,4,16}){var c=new CreeperSimulation{filters=new MeshFilter[n],powerFilters=new MeshFilter[n]};for(int i=0;i<n;i++){c.filters[i]=new MeshFilter{held=new Mesh{name="c"+i}};c.powerFilters[i]=new MeshFilter{held=new Mesh{name="p"+i}};}Mesh.events.Clear();c.Start();for(int i=0;i<n;i++){Need(Object.ReferenceEquals(c.sectionMeshes[i],c.filters[i].held)&&Object.ReferenceEquals(c.powerSectionMeshes[i],c.powerFilters[i].held),"stored identity");Need(c.filters[i].reads==1&&c.powerFilters[i].reads==1,"getter count");Need(c.sectionMeshes[i].marks==(patched?1:0)&&c.powerSectionMeshes[i].marks==0,"only actual creeper meshes hinted");Need(c.payload[i]==i+7&&c.sectionMeshes[i].vertices[1]==2f,"payload unchanged");int at=i*(patched?4:3);Need(Mesh.events[at]=="get:c"+i&&Mesh.events[at+(patched?2:1)]=="store:"+i&&Mesh.events[at+(patched?3:2)]=="get:p"+i,"existing operation order");if(patched)Need(Mesh.events[at+1]=="hint:c"+i,"hint follows getter");checks+=patched?6:5;}}Console.WriteLine("Creeper mesh initialization checks="+checks+" patched="+patched);}
 static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
}
